/** Introductory walkthroughs for backend, mobile and console tracks. */
export const otherBeginnerNotes: Record<string, Record<string, [string, ...string[]]>> = {
  "node-web": {
    "node-v8-callback": ["Node.js est le programme qui exécute ton JavaScript hors du navigateur ; V8 est son moteur JavaScript. Le fichier index.js contient tes instructions. Un callback est une fonction confiée à un autre traitement pour être appelée au moment prévu. L’asynchronisme permet d’attendre une opération sans bloquer tous les autres traitements.", "Lance node index.js depuis le dossier du fichier. Lis la différence entre définir une fonction, la transmettre et l’appeler avec des parenthèses."],
    "npm-scripts": ["npm gère des paquets, c’est-à-dire du code réutilisable. npm init -y écrit un package.json avec des valeurs initiales ; il ne crée pas déjà le serveur. Les scripts sont des noms associés à des commandes dans ce fichier. Le dossier courant doit contenir le package.json du projet concerné.", "npm install ajoute les dépendances ; npm run dev lance le script dev lorsqu’il est déclaré. nodemon relance le serveur quand les fichiers changent."],
    "premier-serveur": ["Un serveur est un programme qui attend des requêtes. Express crée une application de routage. app.get associe une demande GET sur un chemin à une fonction qui reçoit req, la requête, et res, la réponse à préparer. app.listen ouvre l’écoute sur un port : ce numéro distingue le service sur la machine.", "Commence par ouvrir http://localhost:3000/ après le démarrage. localhost désigne ton ordinateur ; / est le chemin demandé. res.send envoie ici une réponse texte."],
    "verbes-express": ["CRUD signifie Create, Read, Update, Delete : créer, lire, modifier et supprimer. L’exemple gère des tâches avec id, titre et état. GET lit la liste, POST ajoute une tâche, PUT remplace les champs attendus d’une tâche existante et DELETE la supprime. Le tableau est conservé en mémoire, pas dans une base durable.", "Crée une tâche, note son id, lis-la, modifie-la puis supprime-la. Contrôle le résultat après chaque action. Un redémarrage efface les données stockées seulement en mémoire."],
    "params-et-query": ["Le chemin et les paramètres de recherche ont des rôles différents. Dans /api/tasks/7, 7 identifie une ressource et se lit via req.params.id si la route annonce :id. Dans /api/tasks?done=true, done est un filtre transmis dans la query string. Les données reçues de l’URL sont à vérifier et à convertir selon le besoin.", "Distingue une tâche inexistante d’un filtre qui ne trouve aucune tâche. Une valeur reçue sous forme de texte n’est pas automatiquement un nombre ou un booléen."],
    "body-json": ["Le corps d’une requête transporte notamment les données d’un ajout. JSON signifie JavaScript Object Notation : un format texte structuré. express.json() est un middleware qui lit un corps JSON compatible avant la route. req.body permet ensuite d’accéder à la valeur décodée, dont la forme n’est pas encore une garantie métier.", "Vérifie qu’un titre est un texte non vide avant de l’enregistrer. Le décodage JSON et la validation du contenu sont deux étapes distinctes."],
  },
  "php-web": {
    "composer-artisan": ["Laravel est le framework, PHP le langage, Composer le gestionnaire de dépendances et Artisan l’outil de commandes du projet. Le dossier vendor contient les paquets installés, app ton code applicatif et routes les déclarations de routes. Générer un projet prépare une structure : il reste ensuite à y écrire ses fonctionnalités.", "Dans le projet exporté, composer install installe les dépendances et php artisan serve lance le serveur de développement selon le guide de l’atelier."],
    "routes-laravel": ["Une route associe une méthode HTTP et un chemin à une réponse. GET demande une ressource ; POST soumet une action. Un nom de route est un identifiant utilisé par ton code pour construire l’URL, il n’est pas forcément identique au chemin affiché dans le navigateur.", "Repère routes/web.php, puis suis le chemin jusqu’à la fonction ou au contrôleur. Une variable {id} dans la route devient un paramètre du traitement."],
    "controleur-mvc": ["MVC signifie Model–View–Controller. Le modèle représente les données et leurs règles ; la vue présente le résultat ; le contrôleur reçoit une action et coordonne le traitement. Dans Laravel, les modèles utilisent souvent Eloquent et les vues Blade. Le contrôleur ne doit pas devenir le lieu où l’on recopie tous les détails d’affichage.", "Suis un exemple : une requête arrive, le contrôleur prépare une donnée, puis renvoie une vue qui affiche cette donnée."],
    "html-json-laravel": ["Une réponse HTML décrit une page à consulter ; une réponse JSON transporte des données destinées à un programme. JSON signifie JavaScript Object Notation et respecte une syntaxe texte stricte. Le même serveur peut fournir les deux types de réponses, selon ses routes et les clients attendus.", "Dans le navigateur, compare la page construite et les données brutes. Une application React peut lire le JSON pour fabriquer sa propre présentation."],
    "blade-directives": ["Blade est le moteur de templates de Laravel : un template est une présentation contenant des emplacements pour des valeurs. {{ $nom }} affiche une valeur échappée. @if choisit une branche et @foreach parcourt une collection. Ces instructions sont traitées côté serveur pour fabriquer le HTML envoyé au navigateur.", "Repère les variables fournies par le contrôleur puis retrouve leurs noms dans la vue. Le navigateur reçoit le résultat, pas les instructions PHP de la vue."],
    "blade-layouts": ["Un layout est une structure de présentation commune : document HTML, menu, zone centrale et pied de page. Les vues de contenu remplissent cette structure au lieu de recopier le menu. Un composant Blade regroupe une partie réutilisable et peut recevoir des données pour la personnaliser.", "Modifie la partie commune puis vérifie deux pages qui l’utilisent. Une seule modification doit apparaître dans les deux résultats."],
  },
  "java-web": {
    "initializr-maven": ["Spring Initializr génère la structure d’un projet Spring Boot. Java est le langage, Spring le cadre applicatif et Maven l’outil qui prépare sa construction. pom.xml décrit notamment les dépendances. JDK signifie Java Development Kit : il fournit le compilateur et les outils d’exécution. Une dépendance est une bibliothèque nécessaire au projet.", "Ouvre le dossier contenant pom.xml. Lis la version Java attendue et les commandes du guide avant de lancer le serveur."],
    "injection-java": ["Une classe est un plan pour des objets ; une instance est un objet concret créé selon ce plan. L’injection par constructeur fournit à un objet les services dont il dépend. Le conteneur Spring crée les composants déclarés et peut les transmettre, au lieu de laisser chaque classe construire sa propre copie de tous les services.", "Suis le constructeur du contrôleur jusqu’au service reçu : le paramètre indique ce dont le contrôleur a besoin pour travailler."],
    "mappings-rest": ["Un mapping associe une requête à une méthode Java. @RestController désigne une classe de réponse web ; @GetMapping associe une lecture, @PostMapping une création et d’autres annotations d’autres actions. Une annotation est une information lue par le framework, pas un mot décoratif. REST est un style d’organisation d’API autour des ressources.", "Lis ensemble le chemin de la classe et celui de la méthode. Repère ensuite la valeur renvoyée et le format de la réponse."],
    "parametres-spring": ["Un paramètre de chemin identifie souvent une ressource ; un paramètre de recherche filtre une collection. @PathVariable relie une partie de l’URL à un paramètre Java et @RequestParam une valeur de query string. Le type annoncé permet certaines conversions, mais les contraintes métier demandent encore des vérifications.", "Compare /taches/7 et /taches?done=true. Vérifie séparément l’absence d’un identifiant, une conversion invalide et une ressource introuvable."],
    "dto-request-body": ["DTO signifie Data Transfer Object : objet de transfert de données. Il décrit les champs attendus d’un échange, séparément du modèle de stockage. @RequestBody demande à Spring de décoder le corps de la requête vers ce type. Un JSON lisible et un DTO créé ne garantissent pas encore que les valeurs sont acceptables.", "Une demande de création peut accepter un titre sans accepter un rôle administrateur ou un identifiant imposé par le client."],
    "validation-spring": ["Valider signifie vérifier que les données respectent les règles avant de les utiliser. @NotNull interdit une valeur absente ; @Size vérifie une taille compatible ; @Valid demande l’application des contraintes lors du traitement concerné. Le décodage, la validation et l’autorisation sont trois vérifications différentes.", "Teste une valeur valide puis une valeur refusée, et lis le message retourné. Choisis des messages qui expliquent au client quoi corriger."],
  },
  "kotlin-mobile": {
    "val-var": ["Une variable donne un nom à une valeur. val interdit de réaffecter ce nom après son initialisation ; var permet une nouvelle affectation. Le signe = associe une valeur, il ne compare pas deux valeurs. Un objet désigné par val peut néanmoins posséder un contenu modifiable selon son type.", "Observe une déclaration, une modification autorisée puis un affichage avec println. La sortie de console permet de voir la valeur actuelle."],
    "types-fonctions": ["Int représente un entier, Double un nombre à virgule, String un texte et Boolean vrai ou faux. Un type indique les données attendues et les opérations possibles. Une fonction annoncée par fun peut recevoir des paramètres et renvoyer un résultat ; son appel fournit des arguments concrets.", "Le texte \"12\" n’est pas l’entier 12. Convertis une saisie de manière vérifiée avant de l’utiliser dans un calcul."],
    "conditions-when": ["Une condition choisit un traitement selon un résultat booléen. if teste un cas ; else propose un autre cas. when compare plusieurs possibilités dans une organisation lisible. En Kotlin ces constructions peuvent aussi produire une valeur, lorsqu’elles couvrent les situations requises.", "Prédis le résultat pour une valeur positive, zéro et une valeur négative. Vérifie les limites avant de lancer l’exemple."],
    "boucles-plages": ["Une boucle répète un traitement. Une plage décrit une suite de valeurs ; for parcourt cette suite, tandis que while répète tant que sa condition reste vraie. Une itération est un passage dans la boucle. Le choix de la borne incluse ou exclue change le nombre de répétitions.", "Lis 1..3 comme 1, 2, 3 et observe ce qui change à chaque passage. Avec while, repère l’instruction qui permettra de sortir."],
    "types-nullables": ["null signifie absence de valeur. String représente un texte présent ; String? permet aussi null. Le ? appartient au type : il demande au code de traiter le cas où la donnée manque, au lieu d’agir comme si elle était toujours disponible.", "Compare un texte vide, un texte renseigné et null. Ce sont trois situations possibles distinctes pour une saisie."],
    "safe-call-elvis": ["L’appel sécurisé ?. utilise une propriété ou une méthode seulement si la valeur n’est pas null. L’opérateur Elvis ?: propose une valeur de remplacement lorsque le résultat de gauche est null. Ces outils rendent le traitement d’une absence explicite sans forcer un accès avec !!.", "Lis nom?.length ?: 0 comme « longueur si nom existe, sinon zéro ». Essaie les deux cas pour suivre le résultat."],
  },
  "compose-mobile": {
    "android-studio-activite": ["Android Studio est l’environnement de développement ; le SDK fournit les outils Android ; l’émulateur simule un appareil. Une Activity est un point d’entrée d’interaction de l’application. setContent y installe une interface Compose. Ouvrir le projet et choisir une cible précèdent le lancement.", "Repère le fichier de l’activité, puis les dépendances Gradle. Utilise le guide de lancement du projet exporté pour afficher l’écran sur Android."],
    "composable-text-image-icon": ["Une fonction @Composable décrit une partie d’écran. Text affiche un texte, Image une image et Icon un pictogramme. Une description d’interface peut être réévaluée lors d’une recomposition, quand les données observées changent. Elle doit donc rester prévisible et ne pas lancer des actions extérieures sans contrôle.", "Ajoute un composant à la fois. Pour une image informative, prévois une description accessible adaptée ; pour une décoration, évite une annonce inutile."],
    "column-row-box": ["Un conteneur organise les éléments enfants. Column les place verticalement, Row horizontalement et Box permet notamment de superposer des contenus. Les réglages d’alignement et d’espace sont relatifs à ce conteneur. Les noms ne représentent pas des coordonnées fixes dans tous les écrans.", "Dessine mentalement le parent et ses enfants, puis change seulement le type de conteneur pour observer la disposition."],
    "modifiers-compose": ["Modifier décrit des réglages appliqués à un composable : taille, espaces, fond et interactions. Une chaîne de Modifier applique ces réglages dans un ordre qui peut changer le résultat. dp représente une unité indépendante de la densité pour les dimensions, sp une unité adaptée au texte et aux préférences de taille.", "Inverse padding et background puis compare la zone colorée. L’ordre explique la différence visible."],
    "boutons-compose": ["Un bouton reçoit une action onClick sous forme de fonction. Une donnée d’état observable permet ensuite d’actualiser la présentation. remember conserve une valeur entre certaines recompositions ; mutableStateOf fournit un état observé. Un simple changement de variable locale ne remplace pas cette relation avec l’interface.", "Suis le trajet : pression → action → changement d’état → recomposition → nouveau texte. Ne déclenche pas l’action directement pendant la description du bouton."],
    "champs-compose": ["Un champ de saisie présente une valeur et signale ses modifications. L’application conserve cette valeur dans un état puis la retransmet au champ. Un mot de passe masqué change la présentation du texte, pas sa sécurité de stockage ou d’envoi. Un libellé explique ce qui est attendu.", "Observe value et onValueChange ensemble. Vérifie la saisie avant une action de validation et présente un message compréhensible si elle est incorrecte."],
  },
  "java-mobile": {
    "ouvrir-projet-java": ["Un projet Android contient du code, des ressources et une configuration de construction. Gradle orchestre ces éléments ; le JDK fournit les outils Java. L’APK est le paquet installable. Sur Android, le code est transformé en bytecode DEX et exécuté par ART, Android Runtime, plutôt que lancé directement comme un fichier .java.", "Ouvre le projet dans Android Studio, attends sa synchronisation puis choisis un appareil ou un émulateur avant Run."],
    "composer-xml": ["XML signifie eXtensible Markup Language : un langage de balisage extensible. Dans les ressources Android, les balises décrivent des vues et conteneurs. Un attribut précise une propriété. @+id crée un identifiant de ressource ; cet identifiant permettra au code Java de retrouver la vue.", "Repère le conteneur parent puis les TextView et Button enfants. Les dimensions et espacements influencent la présentation, pas la logique de clic."],
    "classe-score-java": ["Une classe décrit des attributs et des méthodes ; un objet est une instance créée d’après cette description. Un constructeur initialise l’état de départ. Deux objets Score peuvent évoluer séparément : modifier l’un ne signifie pas modifier l’autre. private limite l’accès direct aux détails internes de la classe.", "Crée mentalement deux scores et suis leurs valeurs après chaque appel de méthode. Distingue le modèle du score et le texte qui l’affiche."],
    "vues-et-clics-java": ["Une vue Android est un élément d’interface comme un bouton. findViewById cherche une vue installée dans l’activité à partir de son identifiant. Un listener est une fonction ou un objet enregistré pour réagir à un événement. setOnClickListener prépare l’action à réaliser lors d’un clic.", "Installe d’abord le contenu de l’activité puis retrouve les vues. L’écouteur modifie les données et actualise les textes concernés."],
    "cycle-activite-java": ["Une activité traverse un cycle de vie : création, visibilité, interaction, pause et arrêt. Le système peut la recréer, par exemple après certains changements de configuration. Une variable d’objet ne suffit donc pas toujours pour conserver une information importante entre deux créations.", "Repère onCreate et les mécanismes de sauvegarde d’état. Vérifie la valeur après une recréation au lieu de tester seulement plusieurs clics."],
    "ouvrir-activite-intent": ["Un Intent décrit une demande d’action Android. Un intent explicite peut indiquer l’activité à ouvrir et lui transmettre de petites données supplémentaires, appelées extras. La navigation crée un contexte d’écran distinct ; elle ne partage pas automatiquement toutes les variables du premier écran.", "Déclare les activités nécessaires selon le manifeste du projet. Lis les extras en tenant compte des valeurs absentes ou invalides."],
  },
  "swift-mobile": {
    "ouvrir-xcode-ios": ["Xcode est l’environnement Apple qui construit et lance les applications iOS. Un simulateur reproduit certains comportements d’un appareil sur Mac. Le projet contient une cible, c’est-à-dire une configuration de produit à construire. Swift est compilé ; SwiftUI est la bibliothèque qui décrit l’interface.", "Choisis la cible et un simulateur compatibles avec le projet exporté. La disponibilité du compilateur Swift sur Windows ne fournit pas SwiftUI iOS sur Windows."],
    "variables-et-optionnels-swift": ["var autorise la réaffectation ; let fixe l’association initiale. Une structure regroupe des valeurs et des comportements. Un optionnel, comme String?, contient soit une valeur soit nil, l’absence de valeur. Lire cette valeur demande de traiter explicitement l’absence plutôt que de supposer qu’un texte existe toujours.", "Utilise if let ou une autre vérification adaptée avant d’employer la valeur. Teste séparément une chaîne vide et un optionnel nil."],
    "protocole-view-swiftui": ["Un protocole est un contrat de capacités. Une structure qui adopte View doit fournir un body décrivant du contenu d’interface. Text construit une vue texte. L’approche est déclarative : tu décris la présentation selon les données plutôt que déplacer manuellement chaque pixel après chaque événement.", "Lis la déclaration de structure, sa conformité à View puis le contenu de body. some View indique un type de vue concret masqué derrière ce contrat."],
    "stacks-et-modificateurs-swiftui": ["VStack dispose les vues verticalement, HStack horizontalement et ZStack en superposition. Un modificateur transforme une vue ou son comportement et renvoie une nouvelle description de vue. L’ordre des modificateurs compte pour le dessin, notamment pour le fond et les espaces.", "Teste padding avant puis après background et observe la surface colorée. Identifie le conteneur parent avant de régler l’alignement des enfants."],
    "state-score-swiftui": ["@State donne à SwiftUI une mémoire locale associée à la vue. Quand sa valeur change, la présentation qui en dépend peut être recalculée. Une action de bouton peut modifier ce score ; le texte lit la valeur actuelle. La vue est une description, l’état conserve la donnée qui la pilote.", "Prédis le texte avant et après un clic. Garde une seule source de vérité pour le score au lieu d’en maintenir deux copies indépendantes."],
    "actions-et-transition-compteur": ["Une action de bouton regroupe les instructions exécutées à la pression. Une transition décrit l’apparition ou le retrait d’une vue, tandis qu’une animation fait évoluer des propriétés dans le temps. La logique de calcul du score doit rester claire avant d’ajouter l’effet visuel.", "Teste les limites du score puis l’animation. Prévois un résultat compréhensible même lorsque les préférences d’accessibilité réduisent les mouvements."],
  },
  "flutter-mobile": {
    "sdk-flutter-et-appareil": ["SDK signifie Software Development Kit : kit de développement. Flutter fournit ses commandes et bibliothèques ; Dart est le langage. flutter doctor vérifie l’installation et les outils des cibles. Une cible est la plateforme ou l’appareil sur lequel construire puis lancer l’application.", "Prépare une cible disponible avant flutter run. Une application native de production peut être compilée à l’avance ; les essais de développement privilégient d’autres mécanismes pour accélérer les modifications."],
    "dart-types-et-constructeurs": ["Un type précise la catégorie attendue d’une valeur. Dart applique la null safety : un type non nullable n’accepte pas null, tandis qu’un type avec ? le permet. Un constructeur initialise un objet. Les paramètres nommés permettent d’indiquer clairement quelle propriété reçoit chaque argument.", "Dans Text('Bonjour'), Text est le constructeur d’un widget. Apprends à lire séparément un argument positionnel et un argument nommé comme style:."],
    "statelesswidget-carte": ["Un widget est une description d’une partie d’interface. StatelessWidget n’héberge pas son propre état mutable dans un objet State associé. Sa méthode build décrit le résultat à partir des informations reçues. Cela ne signifie pas que sa présentation ne peut jamais changer : elle peut être reconstruite avec d’autres données.", "Repère les paramètres du widget puis le résultat renvoyé par build. Commence par une carte fixe avant d’introduire un compteur."],
    "row-column-stack-flutter": ["Row organise horizontalement, Column verticalement et Stack superpose. Les widgets sont disposés selon les contraintes transmises par leurs parents. MainAxis désigne l’axe principal du conteneur ; CrossAxis l’axe transversal. Les espaces et alignements dépendent de la taille disponible.", "Dessine l’arbre des widgets puis modifie un conteneur à la fois. Une Row ne fournit pas une largeur infinie à son contenu sans règle de répartition adaptée."],
    "statefulwidget-compteur": ["Un StatefulWidget décrit une configuration ; un objet State associé conserve les données locales qui peuvent évoluer. La séparation permet à Flutter de reconstruire des descriptions de widgets tout en conservant l’état associé lorsque l’identité est maintenue. Le compteur est une donnée ; Text n’en est que la présentation.", "Repère createState, la variable de score et build. La création d’un nouvel état et la reconstruction d’un widget sont deux événements différents."],
    "setstate-flutter": ["setState annonce une modification des données de l’objet State afin de programmer une reconstruction. Son callback réalise le changement de manière synchrone ; les traitements asynchrones se préparent à l’extérieur selon le besoin. Une affectation silencieuse ne suffit pas toujours à informer l’interface.", "Suis pression → changement du score → reconstruction → affichage. Garde les opérations de calcul séparées de ce qui décrit les widgets."],
  },
  "react-native-mobile": {
    "demarrer-expo-go": ["Expo fournit des outils autour de React Native. Expo Go ouvre les projets compatibles sur un téléphone ; le serveur de développement prépare leur code. Un SDK est un kit de développement avec ses versions de bibliothèques. Une fonctionnalité native absente d’Expo Go peut demander une construction de développement.", "Lance le projet depuis son dossier, puis utilise l’appareil compatible décrit par le guide. Le partage de code n’efface pas les différences entre Android et iOS."],
    "structure-projet-react-native": ["Le point d’entrée est le code appelé pour installer l’application. Un composant décrit une partie d’écran en JSX ou TSX. Le fichier de configuration déclare les outils et dépendances ; les dossiers de sources regroupent tes composants. React Native utilise des éléments natifs plutôt que les balises HTML du navigateur.", "Repère l’enregistrement de l’application puis le premier composant affiché. Suis les imports pour comprendre quel fichier fournit chaque élément."],
    "view-text-image-pressable": ["View est un conteneur, Text présente du texte, Image affiche une image et Pressable réagit à une pression. Ce sont des composants React Native. On combine les composants comme un arbre, avec des parents et des enfants, en leur transmettant des props, les données d’entrée de présentation.", "Place le texte dans Text et décris les contrôles interactifs avec des libellés accessibles. Un nom ressemblant à HTML ne garantit pas les mêmes propriétés."],
    "styles-flexbox-react-native": ["StyleSheet organise des objets de styles JavaScript. Flexbox règle la disposition des enfants, mais ses valeurs par défaut et les propriétés disponibles diffèrent parfois du web. flexDirection choisit un axe ; justifyContent règle l’axe principal et alignItems l’axe transversal.", "Commence par une View avec deux enfants puis change la direction. Les dimensions numériques React Native ne s’écrivent pas comme des chaînes CSS avec px."],
    "textinput-onchangetext": ["TextInput est un champ. value présente le texte actuel et onChangeText fournit le nouveau texte au code. useState peut conserver cette valeur. Un champ contrôlé relie ces deux côtés pour éviter de maintenir une saisie et un état contradictoires.", "Une saisie de chiffres reste un texte tant qu’une conversion vérifiée ne l’a pas transformée en nombre. Un clavier numérique n’est pas à lui seul une validation."],
    "usestate-et-votes": ["Un state est une donnée locale suivie par React. useState renvoie sa valeur actuelle et une fonction de mise à jour. Pour calculer depuis la dernière valeur, utilise une fonction de mise à jour. Deux participants peuvent avoir des états séparés ; un total peut être calculé à partir de leurs scores.", "Suis la donnée qui change après chaque pression et les textes qui en dépendent. Évite de stocker un total recalculable dans une deuxième variable indépendante."],
  },
  "lang-c": {
    "c-premiere-compilation": ["Un fichier source contient du texte en C. Le compilateur vérifie sa syntaxe puis le transforme, avec d’autres outils, en exécutable. main est le point d’entrée. #include annonce un en-tête qui déclare des fonctions comme printf. Les accolades délimitent un bloc et le point-virgule termine de nombreuses instructions.", "Lis main, les instructions dans son bloc puis le code de retour. Dans l’atelier, Compiler et exécuter réalise les deux étapes ; une erreur de compilation n’est pas une sortie normale du programme."],
    "c-types-variables": ["Une déclaration précise un type et un nom ; l’initialisation lui donne une première valeur. int représente un entier, double une valeur à virgule flottante et char un caractère. Le type influence la mémoire utilisée et les opérations autorisées. = affecte une valeur ; il ne signifie pas « est égal à » dans une condition.", "Associe chaque format printf au type attendu, par exemple %d pour int. Observe un texte avec guillemets et un nombre sans guillemets."],
    "c-saisie": ["La saisie provient d’un flux d’entrée, stdin. Le programme doit vérifier qu’il a effectivement reçu une donnée au format attendu avant de l’utiliser. Une conversion ratée ne fournit pas magiquement un nombre correct. Certaines fonctions ont besoin de l’adresse d’une variable pour écrire sa valeur.", "Avec scanf, le résultat indique les conversions réussies. Lis ce test avant le calcul, puis essaie une entrée valide et une entrée incorrecte."],
    "c-conditions": ["Une condition choisit un bloc selon un test. if évalue un cas, else propose le cas contraire et switch répartit selon une valeur parmi des cas. Les opérateurs de comparaison comme == ou > produisent un résultat utilisable dans ces tests.", "Distingue = et ==. Dans switch, observe le rôle de break pour éviter d’exécuter involontairement le cas suivant."],
    "c-boucles": ["Une boucle répète un bloc. for regroupe souvent initialisation, condition et progression ; while annonce seulement une condition. À chaque passage, une itération s’effectue. La condition doit pouvoir devenir fausse pour les traitements qui doivent se terminer.", "Commence par trois valeurs, prédis les sorties puis exécute. Vérifie si la comparaison utilise < ou <= : cela change les limites."],
    "c-fonctions": ["Une fonction décrit un traitement nommé. Ses paramètres reçoivent les valeurs fournies lors d’un appel ; return renvoie un résultat compatible avec son type de retour. Déclarer une fonction indique son contrat ; la définir fournit son corps. Afficher un calcul et retourner ce calcul sont deux actions distinctes.", "Lis la signature avant le corps : type de retour, nom puis paramètres. Suis ensuite un appel avec de petites valeurs faciles à calculer."],
    "c-tableaux": ["Un tableau C contient un nombre d’éléments de même type. Un indice choisit une position à partir de zéro. Le programme doit conserver ou transmettre la taille pour parcourir les éléments sans dépasser leurs limites. Le langage ne vérifie pas automatiquement chaque accès comme une liste Python.", "Pour une taille de 3, les indices valides sont 0, 1 et 2. Une condition indice < taille permet ce parcours."],
    "c-fichiers": ["Séparer les sources organise le programme. Un en-tête .h déclare les fonctions partagées ; un fichier .c fournit leurs définitions. #include rend une déclaration visible ; il ne remplace pas l’assemblage des unités lors de l’édition des liens. Une fonction doit avoir une définition cohérente avec sa déclaration.", "Repère le même nom de fonction dans l’en-tête, sa définition et son appel. Observe les fichiers réellement compilés par la commande."],
  },
  "lang-cpp": {
    "cpp-demarrer": ["C++ est généralement compilé en programme natif. Le source .cpp est du texte ; le compilateur et l’éditeur de liens construisent l’exécutable. main est le point d’entrée. std est l’espace de noms de la bibliothèque standard ; std::cout écrit des données dans le flux de sortie.", "Lis std::cout << \"Bonjour\" comme une insertion du texte dans la sortie. Compile avant de chercher un résultat d’exécution."],
    "cpp-entrees": ["std::cin lit dans le flux d’entrée et convertit selon le type demandé. Une extraction de mot n’a pas le même comportement que getline, qui lit une ligne. Une conversion peut échouer et placer le flux dans un état d’erreur : il faut vérifier cet état avant d’utiliser la donnée.", "Teste un nombre puis un texte inattendu. Si plusieurs lectures se suivent, observe les caractères qui restent dans l’entrée."],
    "cpp-conditions-boucles": ["if choisit un bloc selon une condition ; for et while répètent un traitement. La comparaison == se distingue de l’affectation =. Un bloc est délimité par des accolades, et les variables déclarées dans ce bloc ont une portée limitée à ce contexte.", "Prédis une petite suite de valeurs et contrôle les bornes. Avec une boucle, identifie ce qui avance et ce qui arrête le traitement."],
    "cpp-fonctions": ["Une fonction annonce un type de retour, un nom et des paramètres. L’appel fournit les arguments ; return remet le résultat au code qui l’a appelée. Une variable locale appartient à l’appel en cours et ne devient pas automatiquement accessible ailleurs.", "Distingue le calcul du résultat et son affichage. Une fonction de calcul peut ainsi être réutilisée dans une console puis dans une fenêtre."],
    "cpp-references": ["Une copie crée une valeur distincte ; une référence désigne un objet existant. Le symbole & dans une déclaration de référence fait partie du type déclaré. const interdit certaines modifications à travers le nom concerné. const Type& permet souvent de consulter un objet sans le copier.", "Observe si une fonction modifie l’original ou une copie. Le choix doit être explicite et cohérent avec le rôle annoncé de la fonction."],
    "cpp-classe": ["Une classe est un plan qui regroupe des attributs, les données, et des méthodes, les fonctions liées à ces données. private limite l’accès direct aux détails ; public expose les opérations autorisées. L’encapsulation sert à maintenir des règles plutôt qu’à ajouter des mots sans raison.", "Pour un compteur, garde sa valeur interne et expose une méthode qui l’incrémente selon les limites prévues."],
    "cpp-constructeur-instances": ["Un constructeur prépare une nouvelle instance de classe. Chaque objet créé peut conserver son état propre. Deux compteurs utilisent le même plan de classe mais ne partagent pas nécessairement leurs valeurs. Une liste d’initialisation prépare directement les attributs au moment de la construction.", "Construis deux instances avec des valeurs de départ différentes puis modifie une seule instance. Compare leurs résultats."],
    "cpp-string-vector": ["std::string représente un texte et std::vector une collection redimensionnable de valeurs. La taille indique le nombre d’éléments présents ; un indice désigne leur position. Ajouter des éléments peut déplacer le stockage interne du vector, ce qui compte lorsque l’on conserve des références vers ses éléments.", "Commence par ajouter et parcourir quelques valeurs. Lis size avant un accès et distingue la collection d’un élément de cette collection."],
  },
  "lang-java": {
    "java-demarrer": ["JDK signifie Java Development Kit : kit de développement. javac compile un fichier .java en bytecode .class ; la JVM, Java Virtual Machine, exécute ce bytecode. Java combine donc compilation et exécution par machine virtuelle, avec interprétation ou JIT. La méthode main est le point d’entrée du programme de console.", "Repère la classe publique et le nom du fichier. System.out.println écrit une ligne dans la sortie ; les guillemets délimitent un texte."],
    "java-variables": ["Une variable Java possède un type déclaré qui limite les valeurs qu’elle peut recevoir. int représente un entier, double un nombre à virgule, boolean vrai ou faux et String du texte. final interdit de réaffecter la variable après son initialisation, sans rendre automatiquement tous les objets immuables.", "Lis type, nom puis valeur. Le signe = est une affectation, tandis que les conditions utilisent des comparaisons."],
    "java-scanner": ["Scanner est une classe qui lit et analyse des données depuis une source, ici l’entrée standard. new crée une instance ; une méthode de cette instance réalise une lecture. Lire un entier et lire une ligne de texte n’absorbent pas exactement les mêmes caractères.", "Suis les lectures dans l’ordre et vérifie les conversions. Une saisie invalide doit être traitée avant le calcul."],
    "java-string": ["String représente du texte et fournit des méthodes pour l’observer. Deux variables peuvent viser des objets différents qui contiennent le même texte. == compare l’identité des références d’objet, tandis que equals compare le contenu selon la définition de la classe.", "Pour des textes, utilise une comparaison de contenu adaptée et traite le cas null. Une chaîne vide n’est pas une référence absente."],
    "java-conditions-boucles": ["Une condition if choisit une branche ; une boucle for répète des instructions. Les accolades regroupent les blocs et la portée détermine où une variable est accessible. Le premier indice d’un tableau commence à zéro, et une borne finale mal choisie peut dépasser sa taille.", "Prédis les valeurs de départ, de fin et le nombre de passages. Teste ensuite une collection vide et une collection avec plusieurs éléments."],
    "java-methodes": ["Une méthode est une fonction associée à une classe ou un objet. Sa signature indique les paramètres et le type de résultat. void signifie qu’aucune valeur n’est renvoyée. Une méthode static appartient à la classe ; une méthode d’instance s’utilise sur un objet créé.", "N’assimile pas System.out.println à return : le premier affiche, le second transmet un résultat au code appelant."],
    "java-arraylist": ["ArrayList est une collection redimensionnable. Le type entre chevrons précise les éléments attendus, comme ArrayList<String> pour du texte. add ajoute un élément, get lit une position et size donne le nombre d’éléments. L’indice du dernier élément vaut size moins un.", "Parcours d’abord la collection sans la modifier pendant l’itération. Observe ce qui change après un ajout ou un retrait."],
    "java-classes-instances": ["Une classe décrit un plan commun ; new construit une instance. Un constructeur initialise ses attributs. Un getter expose une lecture et un setter peut appliquer des règles à une modification. Ces méthodes ne sont utiles que si leur rôle est clair : elles ne rendent pas automatiquement un modèle correct.", "Crée deux profils et vérifie qu’une modification de l’un ne remplace pas l’autre. Une méthode peut consulter this pour désigner l’instance courante."],
  },
  "lang-python": {
    "py-interpreteur": ["Un script Python est un fichier texte .py. CPython, l’implémentation habituelle, prépare du bytecode puis l’exécute : on dit généralement que Python est interprété. L’indentation marque les blocs ; elle n’est pas seulement décorative. Les guillemets délimitent un texte et print envoie une représentation de la valeur vers la console.", "Lis les instructions de haut en bas. Après une ligne se terminant par : qui ouvre un bloc, décale ses instructions de façon cohérente, habituellement avec quatre espaces."],
    "py-types-saisie": ["input lit une ligne et renvoie toujours une chaîne de caractères. int et float convertissent un texte compatible en nombre ; une conversion peut échouer. Python associe des noms à des valeurs, et le type de chaque valeur détermine ses opérations. bool représente vrai ou faux.", "Compare '2' + '3' et 2 + 3. Le premier assemble des textes ; le second calcule une somme."],
    "py-conditions": ["if signifie « si », elif « sinon si » et else « sinon ». Une condition est évaluée pour choisir un bloc indenté. == compare des valeurs alors que = affecte. Les opérateurs and, or et not combinent ou inversent des conditions ; l’ordre et les parenthèses doivent rendre ton intention lisible.", "Teste une valeur en dessous, sur et au-dessus de chaque limite. Une branche non choisie n’est pas exécutée."],
    "py-boucles": ["for parcourt une collection ou une suite fournie par range. range(3) produit 0, 1 et 2 : sa borne supérieure est exclue. while répète tant qu’une condition reste vraie. Une itération est un passage dans le bloc ; repère la donnée qui évolue et le moment où le traitement se termine.", "Écris les trois valeurs attendues sur papier avant l’exécution puis compare. Un décalage d’une unité vient souvent des bornes choisies."],
    "py-fonctions": ["def définit une fonction et nomme ses paramètres. Le bloc indenté est son corps. Appeler la fonction avec des parenthèses lui fournit des arguments et lance ce corps. return renvoie un résultat ; une fonction sans return explicite renvoie None. Afficher une valeur ne la transmet pas automatiquement au code appelant.", "Décompose une opération en entrée, calcul et résultat. Une fonction de calcul devient plus réutilisable si son affichage est laissé au code appelant."],
    "py-listes": ["Une liste Python regroupe des valeurs dans un ordre. Son premier indice vaut zéro. append ajoute un élément ; pop retire et renvoie un élément ; len donne la taille. La liste est modifiable, et deux noms peuvent désigner la même liste sans être deux copies indépendantes.", "Observe la liste avant et après chaque opération. Teste le cas vide avant de retirer un élément."],
  },
  "lang-javascript": {
    "js-node-runtime": ["Node.js lance ton fichier JavaScript hors du navigateur. V8 exécute le langage avec interprétation et compilation à la volée. Le fichier est du code source ; la console reçoit sa sortie. document et les éléments HTML ne sont pas fournis par Node.js comme dans une page du navigateur.", "Lance le fichier avec la commande adaptée à son extension et lis console.log. Un programme console peut apprendre la logique sans afficher une fenêtre."],
    "js-let-const-portee": ["let autorise la réaffectation, const l’interdit pour le nom déclaré. Un bloc est une zone entre accolades ; la portée dit où un nom est accessible. Une donnée créée dans un bloc n’est pas automatiquement visible ailleurs. const ne fige pas à lui seul le contenu d’un objet ou tableau.", "Suis chaque nom depuis sa déclaration jusqu’à son utilisation. Distingue changer un objet et réaffecter le nom qui le désigne."],
    "js-objets-litteraux": ["Un objet littéral rassemble des propriétés nommées entre accolades. Une propriété associe une clé à une valeur. Le point permet une lecture avec un nom fixe, les crochets permettent notamment un nom calculé. L’objet est une donnée en mémoire et n’est pas automatiquement du JSON texte.", "Dans profil.nom, profil est l’objet et nom la propriété. JSON.stringify produit une représentation JSON compatible selon les valeurs."],
    "js-array-push-pop": ["Un tableau rassemble des valeurs ordonnées. L’indice commence à zéro ; length donne le nombre d’éléments. push ajoute à la fin et pop retire le dernier élément tout en le renvoyant. Ces méthodes modifient le tableau, même si le nom du tableau a été déclaré avec const.", "Observe le résultat renvoyé par la méthode puis le contenu du tableau : ce sont deux informations différentes."],
    "js-controle-strict": ["=== compare sans la conversion implicite de l’égalité faible. Une condition choisit ensuite la branche à exécuter. for…of parcourt les valeurs d’une collection itérable ; la variable de boucle représente la valeur du passage courant, pas automatiquement son indice.", "Teste 1 et '1' pour repérer la différence de type. Prédis les valeurs que for…of va fournir."],
    "js-fleche-retour": ["Une fonction fléchée utilise => pour définir un traitement. Les paramètres décrivent les entrées ; l’appel fournit leurs arguments. Une expression sans accolades peut être renvoyée directement. Avec un bloc d’accolades, return indique le résultat. La définition de la fonction et son appel sont deux moments différents.", "Calcule mentalement une petite entrée puis compare la valeur renvoyée avec ce qu’affiche la console."],
  },
  "lang-typescript": {
    "ts-compilation": ["TypeScript ajoute des types à JavaScript. tsc signifie TypeScript Compiler : il vérifie les types et produit du JavaScript. Les annotations sont principalement effacées ; Node.js exécute le résultat. Une erreur de types apparaît avant l’exécution dans ce cours, mais une compilation réussie ne garantit pas la justesse de tous les calculs.", "Lis le fichier .ts puis distingue les messages de compilation et la sortie du programme JavaScript produit."],
    "ts-types-explicites": ["string désigne un texte, number un nombre et boolean vrai ou faux. Une annotation après : précise le type ; l’inférence permet aussi à TypeScript de le déduire d’une valeur initiale. Ce contrôle décrit les opérations autorisées dans le code ; il n’empêche pas à lui seul des données externes incorrectes d’arriver.", "Compare une valeur numérique et sa version entre guillemets. Ajoute volontairement une opération incompatible puis lis le diagnostic avant de la corriger."],
    "ts-interfaces": ["Une interface décrit la forme attendue d’un objet : noms de propriétés, types et éventuelles méthodes. Elle ne crée pas une instance et ne produit pas une validation automatique à l’exécution. Un objet satisfait ce contrat quand sa forme est compatible selon les règles du compilateur.", "Lis chaque propriété du profil puis construis un exemple complet. Distingue le contrat de type et la donnée réelle."],
    "ts-optionnels-unions": ["Une propriété suivie de ? peut être absente. Une union séparée par | autorise plusieurs possibilités, comme string | null. Il faut réduire ces possibilités par un test avant une opération qui ne convient qu’à l’une d’elles. Une valeur absente n’est pas toujours une chaîne vide.", "Teste la propriété présente puis absente. Utilise une condition ou une valeur de remplacement adaptée au sens de la donnée."],
    "ts-fonctions-typees": ["Les types des paramètres décrivent les valeurs acceptées et le type de retour décrit le résultat annoncé. Un paramètre n’est pas l’argument concret de chaque appel. Le compilateur vérifie les usages compatibles, tandis que le corps de la fonction réalise réellement le traitement.", "Sépare les fonctions qui calculent de celles qui affichent. Une fonction de retour void n’annonce pas une valeur de calcul à réutiliser."],
    "ts-unknown-validation": ["unknown représente une valeur dont la forme n’est pas encore connue. Contrairement à any, il impose de vérifier avant d’accéder aux propriétés. typeof, des tests de null et d’autres conditions peuvent réduire les possibilités. Un cast forcé n’est pas une vérification des données reçues.", "Commence par vérifier objet non nul, puis présence des champs et types de leurs valeurs. Teste des données correctes et mal formées."],
  },
  "lang-php": {
    "php-script-cli": ["PHP signifie PHP: Hypertext Preprocessor. En CLI, Command-Line Interface, le moteur exécute le script dans le terminal. <?php ouvre la zone de code ; echo écrit une sortie. Le navigateur ne peut pas exécuter directement ce code serveur comme du JavaScript de page.", "Lis les instructions dans l’ordre et repère les points-virgules. Un texte entre guillemets est une chaîne, pas un nom de variable."],
    "php-types-readline": ["Une variable commence par $ et désigne une valeur. readline lit une ligne de texte ; une saisie numérique doit être vérifiée puis convertie avant le calcul. Les types comprennent notamment int, float, string et bool. Une conversion forcée n’est pas nécessairement une validation suffisante du contenu.", "Essaie un entier, un texte et une valeur vide. Compare la donnée reçue et la donnée acceptée pour l’opération."],
    "php-conditions": ["if choisit une branche ; elseif propose un autre test ; else traite le cas restant. === compare en tenant compte de la valeur et du type, contrairement à certaines conversions de ==. Le signe = reste une affectation. Les accolades regroupent les instructions d’une branche.", "Teste une valeur numérique et sa version texte pour comprendre pourquoi le choix de comparaison compte."],
    "php-boucles": ["for regroupe souvent un point de départ, une condition et une progression. while répète tant que sa condition reste vraie. Une itération est un passage dans le bloc. Les limites du parcours doivent correspondre aux valeurs disponibles, notamment quand on utilise un tableau.", "Prédis trois passages puis exécute. Observe l’instruction qui fait évoluer la condition d’arrêt."],
    "php-fonctions": ["function définit un traitement nommé. Ses paramètres reçoivent des arguments lors de l’appel. return renvoie une valeur à utiliser ailleurs ; echo l’affiche dans la sortie. Une fonction de calcul n’a pas besoin de mélanger systématiquement calcul et présentation.", "Lis les entrées, le calcul puis le résultat. Vérifie les noms et la portée des variables utilisées dans la fonction."],
    "php-texte-tableaux": ["Un tableau PHP peut associer des clés à des valeurs ; les premiers exemples utilisent souvent des indices numériques. Un texte est une chaîne encodée : strlen compte des octets, tandis qu’une fonction adaptée aux caractères multioctets est nécessaire pour certaines longueurs humaines. UTF-8 représente notamment les accents sur plusieurs octets.", "Compare une chaîne sans accent puis avec accent. Distingue la taille du tableau et la longueur d’un de ses textes."],
  },
  "lang-sql": {
    "sql-base-table": ["SQL signifie Structured Query Language : langage de requêtes structuré. Une base regroupe des tables ; une table organise des lignes de même structure ; une colonne est un champ nommé. Dans contacts, une ligne représente une personne et les colonnes nom, prenom et telephone décrivent ses informations. Le terminal utilise SQLite, un SGBD embarqué, pas un serveur PostgreSQL ou MySQL.", "SELECT demande un résultat, FROM indique la table et * demande toutes les colonnes. Le tableau de résultats n’est pas nécessairement une nouvelle table enregistrée."],
    "sql-types-cle": ["Un type décrit les valeurs attendues d’une colonne. SQLite a un typage souple avec ses propres règles d’affinité : ne le confonds pas avec les contraintes exactes d’autres SGBD. La clé primaire identifie chaque ligne. NULL représente une valeur absente ou inconnue, distincte de zéro et du texte vide.", "Teste une absence avec IS NULL, pas = NULL. Un nom n’est pas un bon identifiant unique si plusieurs personnes peuvent le partager."],
    "sql-create-table": ["CREATE TABLE décrit une structure ; il n’ajoute pas encore les contacts. Chaque définition de colonne précise un nom, un type et des contraintes éventuelles. PRIMARY KEY identifie une ligne, NOT NULL impose une valeur et UNIQUE interdit les doublons concernés. Les parenthèses regroupent les définitions séparées par des virgules.", "Compare la requête et l’onglet Tables après son exécution. Le point-virgule termine l’instruction SQL."],
    "sql-insert-select": ["INSERT INTO ajoute des lignes dans une table existante. La liste des colonnes correspond dans l’ordre à la liste des valeurs. SELECT lit ensuite les colonnes demandées sans modifier les données. Create, Read, Update et Delete forment CRUD ; ici tu pratiques Create au sens ajout d’une donnée et Read au sens lecture.", "Précise les colonnes à l’insertion pour rendre l’exemple lisible. Les chaînes SQL utilisent des apostrophes, par exemple 'Tiana'."],
    "sql-where-like": ["WHERE filtre les lignes selon une condition. AND exige deux conditions vraies ; OR accepte au moins l’une d’elles ; les parenthèses rendent leur combinaison explicite. LIKE compare un motif de texte : % accepte une suite de caractères et _ un seul caractère dans les usages courants.", "Commence par SELECT pour lire les lignes visées. Dans SQLite, les détails de casse et d’Unicode doivent être vérifiés avant de transposer un filtre vers un autre SGBD."],
    "sql-order-limit": ["ORDER BY définit l’ordre de présentation du résultat. ASC trie de manière croissante, DESC décroissante. LIMIT borne le nombre de lignes et OFFSET en saute un certain nombre. Sans tri explicite, l’ordre des lignes n’est pas garanti. Pour une pagination stable, complète le tri avec une clé unique si les noms sont identiques.", "Teste une première page puis la suivante. Les syntaxes de pagination varient entre SQLite, PostgreSQL, MySQL et SQL Server : consulte le guide SGBD du cours."],
  },
};
